import random

def get_player_choice():
    """Get a player's choice (rock, paper, or scissors) from user input."""
    choices = ['rock', 'paper', 'scissors']
    while True:
        player_choice = input("Enter your choice (rock, paper, or scissors): ").lower()
        if player_choice in choices:
            return player_choice
        else:
            print("Invalid input. Please enter a valid choice.")

def play_round(player1, player2):
    """Play a single round of Rock Paper Scissors and determine the winner."""
    choices = ['rock', 'paper', 'scissors']
    player1_choice = choices[choices.index(player1)]
    player2_choice = choices[choices.index(player2)]

    if player1_choice == 'rock' and player2_choice == 'scissors':
        return player1
    elif player1_choice == 'rock' and player2_choice == 'paper':
        return player2
    elif player1_choice == 'paper' and player2_choice == 'rock':
        return player1
    elif player1_choice == 'paper' and player2_choice == 'scissors':
        return player2
    elif player1_choice == 'scissors' and player2_choice == 'paper':
        return player1
    elif player1_choice == 'scissors' and player2_choice == 'rock':
        return player2
    else:
        return 'tie'

def main():
    player1_wins = 0
    player2_wins = 0

    while True:
        player1_choice = get_player_choice()
        player2_choice = random.choice(choices)

        winner = play_round(player1_choice, player2_choice)

        if winner == 'Player 1':
